#!/usr/bin/env bash
# Every plugin file a Llama version has put on disk, by SHA-256, so
# install.sh and uninstall.sh can tell a file Llama wrote (any version) from
# one you changed.
#
#   dist/gen-known-hashes.sh            regenerate dist/known-hashes.tsv on stdout
#   dist/gen-known-hashes.sh --check    is every file of this checkout listed?
#
# Covers every commit that touched the plugin (people install from `main`,
# not only tags), every tag, and the working tree. Run it and commit the
# result whenever manifest.json or shell-plugin/ changes; CI and the release
# workflow run --check, so a commit whose files aren't listed fails.
#
# Line format: <sha256>\t<label>\t<logical path>, tab-separated. Logical
# paths are where the file sits in the plugin copy: plugin/manifest.json,
# plugin/shell-plugin/<file>. The label is the tag or version+commit that
# first shipped the content; only the hash and the path are compared. The
# binary and the launcher aren't listed: the binary is known by the install
# record only, the launcher is rendered by dist/lib.sh.
set -euo pipefail
cd "$(dirname "$0")/.."

hash_stdin() { sha256sum | cut -d' ' -f1; }

# Lines for one git ref.
ref_lines() {
  local ref=$1 label=$2 path
  while IFS= read -r path; do
    printf '%s\t%s\t%s\n' "$(git show "$ref:$path" | hash_stdin)" "$label" "plugin/$path"
  done < <(git ls-tree -r --name-only "$ref" -- manifest.json shell-plugin)
}

# Lines for the working tree.
tree_lines() {
  local label=$1 path
  printf '%s\t%s\t%s\n' "$(hash_stdin <manifest.json)" "$label" plugin/manifest.json
  while IFS= read -r -d '' path; do
    printf '%s\t%s\t%s\n' "$(hash_stdin <"$path")" "$label" "plugin/$path"
  done < <(find shell-plugin -type f -print0 | LC_ALL=C sort -z)
}

ref_label() {
  local ref=$1 tag
  tag="$(git tag --points-at "$ref" | head -1)"
  if [[ -n $tag ]]; then
    echo "$tag"
  else
    echo "$(git show "$ref:manifest.json" | jq -r .version)+$(git rev-parse --short "$ref")"
  fi
}

generate() {
  {
    local ref
    for ref in $(git rev-list --reverse HEAD -- manifest.json shell-plugin) $(git tag -l 'v*'); do
      ref_lines "$ref" "$(ref_label "$ref")"
    done
    tree_lines "$(jq -r .version manifest.json)"
  } | LC_ALL=C sort -t $'\t' -k3,3 -k1,1 -s | awk -F'\t' '!seen[$1 FS $3]++'
}

case "${1:-}" in
  "")
    echo "# generated by dist/gen-known-hashes.sh; do not edit. sha256, first label, logical path."
    generate
    ;;
  --check)
    [[ -f dist/known-hashes.tsv ]] || { echo "dist/known-hashes.tsv is missing" >&2; exit 1; }
    missing=0
    while IFS=$'\t' read -r h _ logical; do
      awk -F'\t' -v h="$h" -v l="$logical" '$1 == h && $3 == l { found = 1 } END { exit !found }' dist/known-hashes.tsv \
        || { echo "not listed: $logical ($h)"; missing=1; }
    done < <(tree_lines check)
    if (( missing )); then
      echo "Run dist/gen-known-hashes.sh > dist/known-hashes.tsv and commit it." >&2
      exit 1
    fi
    echo "known-hashes.tsv covers this checkout."
    ;;
  -h | --help) sed -n '2,19p' "$0" | sed 's/^# \{0,1\}//' ;;
  *) echo "usage: $0 [--check]" >&2; exit 2 ;;
esac
